cat > tests/server/tmp-lifecycle.test.ts <<'EOF'
import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);
import { registerActivityListeners } from "@/server/services/activity-service";
import * as orgService from "@/server/services/organization-service";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { notify } from "@/server/services/notification-service";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import { listActivity } from "@/server/repositories/activity-repository";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerActivityListeners(); });
afterAll(() => cleanup());
it("lifecycle", async () => {
  const t = await createTenant("life");
  await usageRepo.recomputeUsage(t.org.id);
  await orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: "life" } as never);
  await expect(orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: "life" } as never)).rejects.toThrow(/already archived/);
  expect(await usageRepo.listOrgIdsForRollup(10)).not.toContain(t.org.id);
  expect(await orgService.resolveOrgBySlug("life")).toBeNull();
  expect(await notify(t.org.id, "issue_assigned", [t.userIds.member], { title: "a", body: "b", href: "/", actorId: null })).toEqual([]);
  await expect(orgService.restoreOrganization(t.userIds.admin, t.org.id)).rejects.toThrow(/Permission/);
  const back = await orgService.restoreOrganization(t.userIds.owner, t.org.id);
  expect(back.archivedAt).toBeNull();
  const acts = await listActivity({ orgId: t.org.id, limit: 20, cursor: null } as never);
  expect(acts.items.map((a) => a.action)).toEqual(expect.arrayContaining(["organization.deleted", "organization.restored"]));
  await orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: "life" } as never);
  await runCleanupArchivedJob(new Date(Date.now() + 29 * 86400000));
  expect(await orgRepo.findOrgById(t.org.id)).not.toBeNull();
  await runCleanupArchivedJob(new Date(Date.now() + 31 * 86400000));
  expect(await orgRepo.findOrgById(t.org.id)).toBeNull();
  expect(await memberRepo.findMember(t.org.id, t.userIds.owner)).toBeNull();
  await expect(orgService.restoreOrganization(t.userIds.owner, t.org.id)).rejects.toThrow(/not found/);
});
EOF
